export function postLedgerEntries(
  state: Pick<GameState, "ledger" | "treasuryCoin" | "tick" | "scenarioId">,
  postings: readonly LedgerPosting[],
): { readonly ledger: Ledger; readonly treasuryCoin: number } {
  for (const posting of postings) {
    if (!Array.isArray(posting.sourceRefs) || posting.sourceRefs.length === 0) {
      throw new LedgerSourceError(`Ledger entry ${posting.category} has no source`);
    }
    if (!Number.isSafeInteger(posting.amount)) throw new RangeError(`Ledger amount must be whole pennies: ${posting.amount}`);
  }
  let ledger = state.ledger ?? openingLedger(state, "ledger_start");
  const previousCash = accountBalance(ledger, "cash");
  const entries = [...ledger.entries];
  let ordinal = ledger.nextEntryOrdinal;
  let postedCash = 0;
  for (const posting of postings) {
    entries.push({ ...posting, id: ledgerEntryId(ordinal), tick: state.tick });
    if (posting.account === "cash") postedCash += posting.amount;
    ordinal += 1;
  }
  ledger = rollUpLedger({ ...ledger, entries, nextEntryOrdinal: ordinal }, state.tick);
  cashBalances.set(ledger, previousCash + postedCash);
  return { ledger, treasuryCoin: previousCash + postedCash };
}

export const EMPTY_LEDGER: Ledger = { entries: [], rollups: [], nextEntryOrdinal: 1 };

export function ledgerEntryId(ordinal: number): string {
  return `ledger-${String(ordinal).padStart(6, "0")}`;
}

export function historyParams(record: Pick<HistoryRecord, "params">, state?: PersonReader): HistoryParams {
  const params = record.params ?? {};
  if (!namesPerson(record)) return params;
  const named: Record<string, string | number> = { ...params };
  for (const [idKey, nameKey] of Object.entries(PERSON_PARAMS)) {
    const id = params[idKey];
    if (typeof id !== "string") continue;
    const person = state === undefined || id === "" ? undefined : personNamed(state, id);
    named[nameKey] = person !== undefined ? personDisplayName(person) : typeof params[nameKey] === "string" ? params[nameKey] : PERSON_NAME_FALLBACK[nameKey] ?? "";
  }
  return named;
}

/** ES-9: the opening portfolio — the home estate and the three neighbours, read from the seed. */
export function initialEstates(state: Pick<GameState, "seed" | "scenarioId" | "factions">): EstatesState {
  const neighbours = neighbourEstates(state);
  const claims: Claim[] = OPENING_CLAIMS.map((claim, index) => ({ id: `claim-${index + 1}`, claimant: LORD, estateId: claim.estateId,
    pieceId: `${claim.estateId}:${claim.pieceKind}`, basis: claim.basis, strength: CLAIM_BASIS_STRENGTH[claim.basis], evidence: [], since: 0, status: "open" }));
  return { estates: [homeEstate(), ...neighbours.estates], claims, suits: [], nextClaim: claims.length + 1, nextSuit: 1, people: neighbours.people };
}

export function raiseClaim(state: GameState, fields: { readonly claimant: HolderId; readonly estateId: string; readonly pieceId?: string;
  readonly basis: ClaimBasis; readonly strength?: number }): GameState {
  const estates = estatesOf(state);
  if (estates.claims.some(claim => claim.claimant === fields.claimant && claim.estateId === fields.estateId && claim.pieceId === fields.pieceId
    && claim.basis === fields.basis && (claim.status === "open" || claim.status === "suing"))) return state;
  const claim: Claim = { id: `claim-${estates.nextClaim}`, claimant: fields.claimant, estateId: fields.estateId,
    ...(fields.pieceId === undefined ? {} : { pieceId: fields.pieceId }), basis: fields.basis,
    strength: fields.strength ?? CLAIM_BASIS_STRENGTH[fields.basis], evidence: [], since: state.tick, status: "open" };
  return { ...state, estates: { ...estates, claims: [...estates.claims, claim], nextClaim: estates.nextClaim + 1 } };
}
